		t.Fatal("Record blocked behind a stuck sink")
	}
	stats := journal.Stats()
	if stats.Recorded != 50 || stats.DroppedQueue == 0 || stats.Indexed != 50 {
		t.Fatalf("stats = %+v", stats)
	}
	close(sink.block)
	waitFor(t, func() bool { return journal.Stats().Queued == 0 })
	cancel()
	<-done
}

