// withSFO adds sfo to the global view, so the topology links it below the graph.
func withSFO(current view) view {
	current.Global = []globalview.Region{{Cell: "gru"},
		{Cell: "sfo", Rollup: &globalview.Rollup{Cell: "sfo", Health: globalview.Health{Status: globalview.Healthy}}}}
	return current
}

func renderTopology(t *testing.T, current view) string {
	t.Helper()
	return fixturePage(t, current, "/topology")
}

func nodeClass(body, node string) string {
	at := strings.Index(body, `data-node="`+node+`"`)
	if at < 0 {
		return ""
	}
	start := strings.LastIndex(body[:at], `class="`)
	return body[start+len(`class="`) : at-2]
}

type fixedSnapshots struct {
	snapshot observability.MemberSnapshot
	err      error
}

func (source fixedSnapshots) Snapshot(context.Context, bool) (observability.MemberSnapshot, error) {
	return source.snapshot, source.err
}

type fixedCluster struct {
	snapshot observability.ClusterSnapshot
	err      error
	calls    *int
}

func (source fixedCluster) Cluster(context.Context, bool) (observability.ClusterSnapshot, error) {
	if source.calls != nil {
		*source.calls++
	}
	return source.snapshot, source.err
}

func fixturePage(t *testing.T, current view, path string) string {
	t.Helper()
	now := current.Now
	if now.IsZero() {
		now = testNow
	}
	journal := Journal{}
	if current.Journal != nil {
		journal = *current.Journal
	}
	if current.LocalSummary != nil {
		journal.Local = func(context.Context) regionview.Summary { return *current.LocalSummary }
	}
	if current.Global != nil {
		cells := make([]string, 0, len(current.Global))
		for _, region := range current.Global {
			cells = append(cells, region.Cell)
		}
		local := ""
		if len(cells) > 0 {
			local = cells[0]
		}
		journal.Global = globalview.NewView(local, func() []string { return cells }, func() time.Time { return now })
		for _, region := range current.Global {
			if region.Rollup == nil {
				continue
			}
			rollup := *region.Rollup
			rollup.Version, rollup.Cell = globalview.Version, region.Cell
			if rollup.ObservedAt.IsZero() {
				rollup.ObservedAt = now
			}
			if region.Stale {
				rollup.ObservedAt = now.Add(-time.Minute)
			}
			if !journal.Global.Accept(rollup) {
				t.Fatalf("invalid fixture rollup: %+v", rollup)
			}
		}
	}
	if current.Decisions != nil {
		journal.Decisions = fixtureDecisions{result: *current.Decisions}
	}
	if current.Versions != nil {
		journal.Versions = fakeVersions(current.Versions)
	}
	if current.Capacity != nil {
		journal.Capacity = &fakeCapacity{view: *current.Capacity}
	}
	if current.Evaluation != nil {
		journal.Insights = &fakeInsights{evaluation: *current.Evaluation}
	}
	options := Options{Journal: &journal, Now: func() time.Time { return now }, Health: fixtureHealth{current.Ready, current.Checks}}
	if current.Local != nil {
		options.Snapshots = fixedSnapshots{snapshot: *current.Local}
	}
	if current.Cluster != nil {
		options.Cluster = fixedCluster{snapshot: *current.Cluster}
	}
	server := httptest.NewServer(New(options).Handler())
	defer server.Close()
	state := current.State
	if state.Range.Key == "" {
		state = parseState(nil)
	}
	if query := state.query(); query != "" {
		path += "?" + query
	}
	client := server.Client()
	client.Timeout = 5 * time.Second
	response, err := client.Get(server.URL + path)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusOK {
		t.Fatalf("GET %s = %d: %s", path, response.StatusCode, body)
	}
	return string(body)
}

dashboard_handler.text:
// Mount registers every page, its stream, the login form and the assets.
func (dashboard *Dashboard) Mount(mounter Mounter) {
	mounter.HandleStatic("GET /assets/{hash}/{file}", http.HandlerFunc(serveAsset))
	mounter.HandleLogin(dashboard.guard(http.HandlerFunc(dashboard.login)))
	for _, page := range slices.Concat(pages, detailPages) {
		mounter.Handle("GET "+page.path(), dashboard.guard(dashboard.pageHandler(page)))
		mounter.Handle("GET "+page.streamPath(), dashboard.guard(dashboard.streamHandler(page)))
	}
	mounter.Handle("POST /capacity/budget", dashboard.guard(http.HandlerFunc(dashboard.setBudget)))
}

// Handler returns the dashboard routes on their own mux without any
// authentication. Tests use it; production mounts on the private listener.
func (dashboard *Dashboard) Handler() http.Handler {
	mux := http.NewServeMux()
	dashboard.Mount(muxMounter{mux})
	return mux
}

type muxMounter struct{ mux *http.ServeMux }

func (mounter muxMounter) Handle(pattern string, handler http.Handler) {
	mounter.mux.Handle(pattern, handler)
}
func (mounter muxMounter) HandleStatic(pattern string, handler http.Handler) {
	mounter.mux.Handle(pattern, handler)
}
func (mounter muxMounter) HandleLogin(page http.Handler) { mounter.mux.Handle("GET /login", page) }

// contentSecurityPolicy allows only this listener's own files. Datastar
// evaluates its data-* expressions with Function, which needs unsafe-eval;
// there are no inline scripts and no inline style elements. ECharts writes
// its tooltip markup with style attributes, so style-src-attr alone allows
// inline style attributes; templ escapes every server value, so no request
// data can reach an attribute unescaped.
const contentSecurityPolicy = "default-src 'self'; script-src 'self' 'unsafe-eval'; style-src 'self'; " +
	"style-src-attr 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'none'; " +
	"form-action 'self'; frame-ancestors 'none'"

// guard applies the browser hardening headers and the Host check.
func (dashboard *Dashboard) guard(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if dashboard.options.RequireLiteralHost && !literalHost(request.Host) {
			http.Error(writer, "the dashboard must be addressed by IP or localhost", http.StatusMisdirectedRequest)
			return
		}
		header := writer.Header()
		header.Set("Content-Security-Policy", contentSecurityPolicy)
		header.Set("X-Content-Type-Options", "nosniff")
		header.Set("X-Frame-Options", "DENY")
		header.Set("Referrer-Policy", "same-origin")
		header.Set("Cache-Control", "no-store")
		next.ServeHTTP(writer, request)
	})
}

func (dashboard *Dashboard) load(ctx context.Context, page page, query url.Values, path map[string]string) view {
	current := view{Page: page, Now: dashboard.options.Now().UTC(), SignOut: dashboard.options.SignOut,
		Filter: parseEventFilter(query), State: parseState(query), Path: path}
	if region := path["r"]; region != "" {
		// A detail page whose path names its region shows that region.
		current.State.Region = region
	}
	if health := dashboard.options.Health; health != nil {
		current.Ready, current.Checks = health.Evaluate(ctx)
	}
	if holder := dashboard.snapshots.Load(); holder != nil {
		snapshot, err := holder.source.Snapshot(ctx, false)
		if err != nil {
			current.Notes = append(current.Notes, "This member's snapshot is unavailable.")
		} else {
			current.Local = &snapshot
		}
	} else {
		current.Notes = append(current.Notes, "This member is still starting; its providers are not attached yet.")
	}
	if holder := dashboard.cluster.Load(); holder != nil {
		snapshot, err := dashboard.clusters.Get(ctx, func(ctx context.Context) (observability.ClusterSnapshot, error) {
			return holder.source.Cluster(ctx, false)
		})
		if err != nil {
			current.Notes = append(current.Notes, "The cell-wide view is unavailable; showing this member only.")
		} else {
			current.Cluster = &snapshot
		}
	}
	if page.events > 0 && dashboard.options.Events != nil {
		current.Events = current.Filter.apply(dashboard.options.Events.Recent(0), page.events)
	}
	dashboard.loadJournal(ctx, &current)
	return current
}

func (dashboard *Dashboard) pageHandler(page page) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		path, found := page.pathValues(request)
		if !found {
			http.NotFound(writer, request)
			return
		}
		current := dashboard.load(request.Context(), page, request.URL.Query(), path)
		current.loadMetrics(request.Context())
		if page.slug == "region" && current.remote() {
			// The region page shows this member's region only; another one
			// has its own global view.
			http.Redirect(writer, request, "/regions/"+current.State.Region, http.StatusSeeOther)
			return
		}
		render(writer, request, layout(current))
	})
}

func (dashboard *Dashboard) login(writer http.ResponseWriter, request *http.Request) {
	query := request.URL.Query()
	render(writer, request, login(query.Get("failed") == "1", observability.LocalRedirectPath(query.Get("next"))))
}

func render(writer http.ResponseWriter, request *http.Request, component templ.Component) {
	var body bytes.Buffer
	if err := component.Render(request.Context(), &body); err != nil {
		level := slog.LevelWarn
		if errors.Is(err, context.Canceled) {
			// The client went away; nothing is wrong with the dashboard.
			level = slog.LevelDebug
		}
		slog.Log(request.Context(), level, "dashboard render failed", observability.ComponentKey, "dashboard", "error", err)
		http.Error(writer, "render failed", http.StatusInternalServerError)
		return
	}
	writer.Header().Set("Content-Type", "text/html; charset=utf-8")
	writer.Header().Add("Vary", "Accept-Encoding")
	if !acceptsGzip(request.Header.Get("Accept-Encoding")) {
		_, _ = writer.Write(body.Bytes())
		return
	}
	writer.Header().Set("Content-Encoding", "gzip")
	zipped := gzip.NewWriter(writer)
	_, _ = zipped.Write(body.Bytes())
	_ = zipped.Close()

