type fakeSink struct {
	mu        sync.Mutex
	stored    []Decision
	failures  int
	block     chan struct{}
	attempted atomic.Int64
}

func (sink *fakeSink) Publish(ctx context.Context, decision Decision) error {
	sink.attempted.Add(1)
	if sink.block != nil {
		select {
		case <-sink.block:
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	sink.mu.Lock()
	defer sink.mu.Unlock()
	if sink.failures > 0 {
		sink.failures--
		return errors.New("unavailable")
	}
	sink.stored = append(sink.stored, decision)
	return nil
}

func (sink *fakeSink) count() int {
	sink.mu.Lock()
	defer sink.mu.Unlock()
	return len(sink.stored)
}

type fakeArchive struct {
	decisions []Decision
	complete  bool
	scans     atomic.Int64
}

func (archive *fakeArchive) Scan(_ context.Context, since time.Time, maxScan int, visit func(Decision) bool) (bool, error) {
	archive.scans.Add(1)
	scanned := 0
	for _, decision := range archive.decisions {
		if decision.Time.Before(since) {
			continue
		}
		if scanned == maxScan {
			return false, nil
		}
		scanned++
		if !visit(decision) {
			return true, nil
		}
	}
	return archive.complete, nil
}

func waitFor(t *testing.T, condition func() bool) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for !condition() {
		if time.Now().After(deadline) {
			t.Fatal("condition not reached")
		}
		time.Sleep(5 * time.Millisecond)
	}
}

func (journal *Journal) markDurable(id string) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if _, indexed := journal.ids[id]; indexed {
		journal.ids[id] = true
	}
}

// Run publishes queued decisions until ctx ends. A publish is retried a few
// times with the same message ID, so the stream deduplicates a retry whose
// first attempt was stored; a decision that still fails is dropped and
// counted.
func (journal *Journal) Run(ctx context.Context) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case decision := <-journal.queue:
			queueDepth.Add(-1)
			journal.publish(ctx, decision)
		}
	}
}

func (journal *Journal) publish(ctx context.Context, decision Decision) {
	backoff := 250 * time.Millisecond
	for attempt := 1; ; attempt++ {
		sink, _ := journal.currentStorage()
		if sink == nil {
			// No stream yet: wait for one without holding up shutdown.
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
			}
			backoff = min(backoff*2, 5*time.Second)
			attempt = 0
			continue
		}
		publishCtx, cancel := context.WithTimeout(ctx, journal.config.PublishTimeout)
		err := sink.Publish(publishCtx, decision)
		cancel()
		if err == nil {
			journal.published.Add(1)
			publishedTotal.Inc()
			journal.markDurable(decision.ID)
			return
		}
		if ctx.Err() != nil || attempt >= publishAttempts {
			journal.failed.Add(1)
			droppedPublish.Inc()
			return
		}
		publishRetries.Inc()
		select {
		case <-ctx.Done():
			journal.failed.Add(1)
			droppedPublish.Inc()
			return
		case <-time.After(backoff):
		}
		backoff *= 2
	}
}

